def count_islands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    seen = set()

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            y, x = stack.pop()
            if (y, x) in seen or not (0 <= y < rows and 0 <= x < cols) or grid[y][x] == 0:
                continue
            seen.add((y, x))
            stack.extend([(y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)])

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in seen:
                dfs(r, c)
                count += 1
    return count

